class Solution:
    def maxSumTwoNoOverlap(self, nums: List[int], firstLen: int, secondLen: int) -> int:
        n = len(nums)
        P = [0] * (n + 1)
        for i in range(n):
            P[i + 1] = P[i] + nums[i]
        best = 0
        for i in range(n - firstLen + 1):
            sL = P[i + firstLen] - P[i]
            for j in range(0, i - secondLen + 1):
                best = max(best, sL + P[j + secondLen] - P[j])
            for j in range(i + firstLen, n - secondLen + 1):
                best = max(best, sL + P[j + secondLen] - P[j])
        return best

