        long long best = 0;
        for (int i = 0; i + firstLen <= n; i++) {
            long long sL = P[i + firstLen] - P[i];
            for (int j = 0; j + secondLen <= i; j++)
                best = max(best, sL + P[j + secondLen] - P[j]);
            for (int j = i + firstLen; j + secondLen <= n; j++)
                best = max(best, sL + P[j + secondLen] - P[j]);
        }
        return (int)best;
    }
};

