class Solution:
    def maxSumTwoNoOverlap(self, nums: List[int], firstLen: int, secondLen: int) -> int:
        def solve(L, M):
            n = len(nums)
            P = [0] * (n + 1)
            for i in range(n):
                P[i + 1] = P[i] + nums[i]
            leftMax = [0] * n
            cur = 0
            for i in range(M - 1, n):
                cur = max(cur, P[i + 1] - P[i + 1 - M])
                leftMax[i] = cur
            rightMax = [0] * n
            cur = 0
            for i in range(n - M, -1, -1):
                cur = max(cur, P[i + M] - P[i])
                rightMax[i] = cur
            best = 0
            for i in range(n - L + 1):
                sL = P[i + L] - P[i]
                if i > 0:
                    best = max(best, sL + leftMax[i - 1])
                if i + L < n:
                    best = max(best, sL + rightMax[i + L])
            return best
        return max(solve(firstLen, secondLen), solve(secondLen, firstLen))

