class Solution {
public:
    int maxSumTwoNoOverlap(vector<int>& nums, int firstLen, int secondLen) {
        auto solve = [&](int L, int M) {
            int n = nums.size();
            vector<long long> P(n + 1, 0);
            for (int i = 0; i < n; i++) P[i + 1] = P[i] + nums[i];
            vector<long long> leftMax(n, 0), rightMax(n, 0);
            long long cur = 0;
            for (int i = M - 1; i < n; i++) {
                cur = max(cur, P[i + 1] - P[i + 1 - M]);
                leftMax[i] = cur;
            }
            cur = 0;
            for (int i = n - M; i >= 0; i--) {
                cur = max(cur, P[i + M] - P[i]);
                rightMax[i] = cur;
            }
            long long best = 0;
            for (int i = 0; i + L <= n; i++) {
                long long sL = P[i + L] - P[i];
                if (i > 0) best = max(best, sL + leftMax[i - 1]);
                if (i + L < n) best = max(best, sL + rightMax[i + L]);
            }
            return best;
        };
        return (int)max(solve(firstLen, secondLen), solve(secondLen, firstLen));
    }
};

